71	  /**
72	   * This is the default implementation which iterates through the ranges
73	   * to read each synchronously, but the intent is that subclasses
74	   * can make more efficient readers.
75	   * The data or exceptions are pushed into {@link FileRange#getData()}.
76	   * @param stream the stream to read the data from
77	   * @param ranges the byte ranges to read
78	   * @param allocate the byte buffer allocation
79	   */
80	  public static void readVectored(PositionedReadable stream,
81	                                  List<? extends FileRange> ranges,
82	                                  IntFunction<ByteBuffer> allocate) {
83	    for (FileRange range: ranges) {
84	      range.setData(readRangeFrom(stream, range, allocate));
85	    }
86	  }
87	
88	  /**
89	   * Synchronously reads a range from the stream dealing with the combinations
90	   * of ByteBuffers buffers and PositionedReadable streams.
91	   * @param stream the stream to read from
92	   * @param range the range to read
93	   * @param allocate the function to allocate ByteBuffers
94	   * @return the CompletableFuture that contains the read data
95	   */
96	  public static CompletableFuture<ByteBuffer> readRangeFrom(PositionedReadable stream,
97	                                                            FileRange range,
98	                                                            IntFunction<ByteBuffer> allocate) {
99	    CompletableFuture<ByteBuffer> result = new CompletableFuture<>();
100	    try {
101	      ByteBuffer buffer = allocate.apply(range.getLength());
102	      if (stream instanceof ByteBufferPositionedReadable) {
103	        ((ByteBufferPositionedReadable) stream).readFully(range.getOffset(),
104	            buffer);
105	        buffer.flip();
106	      } else {
107	        readNonByteBufferPositionedReadable(stream, range, buffer);
108	      }
109	      result.complete(buffer);
110	    } catch (IOException ioe) {
111	      result.completeExceptionally(ioe);
112	    }
113	    return result;
114	  }
115	
116	  private static void readNonByteBufferPositionedReadable(PositionedReadable stream,
117	                                                          FileRange range,
118	                                                          ByteBuffer buffer) throws IOException {
119	    if (buffer.isDirect()) {
120	      readInDirectBuffer(range.getLength(),
121	          buffer,
122	          (position, buffer1, offset, length) -> {
123	            stream.readFully(position, buffer1, offset, length);
124	            return null;
125	          });
126	      buffer.flip();
127	    } else {
128	      stream.readFully(range.getOffset(), buffer.array(),
129	              buffer.arrayOffset(), range.getLength());
130	    }
131	  }
132	
133	  /**
134	   * Read bytes from stream into a byte buffer using an
135	   * intermediate byte array.
136	   * @param length number of bytes to read.
137	   * @param buffer buffer to fill.
138	   * @param operation operation to use for reading data.
139	   * @throws IOException any IOE.
140	   */
141	  public static void readInDirectBuffer(int length,
142	                                        ByteBuffer buffer,
143	                                        Function4RaisingIOE<Integer, byte[], Integer,
144	                                                Integer, Void> operation) throws IOException {
145	    if (length == 0) {
146	      return;
147	    }
148	    int readBytes = 0;
149	    int position = 0;
150	    int tmpBufferMaxSize = Math.min(TMP_BUFFER_MAX_SIZE, length);
151	    byte[] tmp = new byte[tmpBufferMaxSize];
152	    while (readBytes < length) {
153	      int currentLength = (readBytes + tmpBufferMaxSize) < length ?
154	              tmpBufferMaxSize
155	              : (length - readBytes);
156	      operation.apply(position, tmp, 0, currentLength);
157	      buffer.put(tmp, 0, currentLength);
158	      position = position + currentLength;
159	      readBytes = readBytes + currentLength;
160	    }
161	  }
