318	    @Override
319	    public void readVectored(List<? extends FileRange> ranges,
320	                             IntFunction<ByteBuffer> allocate) throws IOException {
321	
322	      List<? extends FileRange> sortedRanges = Arrays.asList(sortRanges(ranges));
323	      // Set up all of the futures, so that we can use them if things fail
324	      for(FileRange range: sortedRanges) {
325	        VectoredReadUtils.validateRangeRequest(range);
326	        range.setData(new CompletableFuture<>());
327	      }
328	      try {
329	        AsynchronousFileChannel channel = getAsyncChannel();
330	        ByteBuffer[] buffers = new ByteBuffer[sortedRanges.size()];
331	        AsyncHandler asyncHandler = new AsyncHandler(channel, sortedRanges, buffers);
332	        for(int i = 0; i < sortedRanges.size(); ++i) {
333	          FileRange range = sortedRanges.get(i);
334	          buffers[i] = allocate.apply(range.getLength());
335	          channel.read(buffers[i], range.getOffset(), i, asyncHandler);
336	        }
337	      } catch (IOException ioe) {
338	        LOG.debug("Exception occurred during vectored read ", ioe);
339	        for(FileRange range: sortedRanges) {
340	          range.getData().completeExceptionally(ioe);
341	        }
342	      }
343	    }
344	  }
