346	  /**
347	   * A CompletionHandler that implements readFully and translates back
348	   * into the form of CompletionHandler that our users expect.
349	   */
350	  static class AsyncHandler implements CompletionHandler<Integer, Integer> {
351	    private final AsynchronousFileChannel channel;
352	    private final List<? extends FileRange> ranges;
353	    private final ByteBuffer[] buffers;
354	
355	    AsyncHandler(AsynchronousFileChannel channel,
356	                 List<? extends FileRange> ranges,
357	                 ByteBuffer[] buffers) {
358	      this.channel = channel;
359	      this.ranges = ranges;
360	      this.buffers = buffers;
361	    }
362	
363	    @Override
364	    public void completed(Integer result, Integer r) {
365	      FileRange range = ranges.get(r);
366	      ByteBuffer buffer = buffers[r];
367	      if (result == -1) {
368	        failed(new EOFException("Read past End of File"), r);
369	      } else {
370	        if (buffer.remaining() > 0) {
371	          // issue a read for the rest of the buffer
372	          // QQ: What if this fails? It has the same handler.
373	          channel.read(buffer, range.getOffset() + buffer.position(), r, this);
374	        } else {
375	          // QQ: Why  is this required? I think because we don't want the
376	          // user to read data beyond limit.
377	          buffer.flip();
378	          range.getData().complete(buffer);
379	        }
380	      }
381	    }
382	
383	    @Override
384	    public void failed(Throwable exc, Integer r) {
385	      LOG.debug("Failed while reading range {} ", r, exc);
386	      ranges.get(r).getData().completeExceptionally(exc);
387	    }
388	  }
